import { useEffect, useRef, useState } from "react";
import HeroCard from "./HeroCard";
import { lerp, clamp, ease } from "./helpers";
import '../index.css';

const CARDS = [
  { id: 1,  label: "Vehicle RC",      angle: 180,   rotate: -14, z: 26 },
  { id: 2,  label: "DL Verification", angle: 147.3, rotate: 9,   z: 27 },
  { id: 3,  label: "KYC Check",       angle: 114.5, rotate: -6,  z: 28 },
  { id: 4,  label: "Aadhaar",         angle: 81.8,  rotate: 5,   z: 29 },
  { id: 5,  label: "Face Match",      angle: 49.1,  rotate: -9,  z: 29 },
  { id: 6,  label: "PAN Card",        angle: 16.4,  rotate: 12,  z: 28 },
  { id: 7,  label: "Fraud Alert",     angle: 343.6, rotate: -5,  z: 27 },
  { id: 8,  label: "Bank Verify",     angle: 310.9, rotate: 11,  z: 28 },
  { id: 9,  label: "Credit Score",    angle: 278.2, rotate: -5,  z: 29 },
  { id: 10, label: "Background Chk",  angle: 245.5, rotate: -10, z: 28 },
  { id: 11, label: "Employment",      angle: 212.7, rotate: 9,   z: 27 },
];

export default function HeroSection() {
  const [progress, setProgress] = useState(0);
  const [vw, setVw]             = useState(0);
  const sectionRef              = useRef(null);

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const p = clamp(
        -el.getBoundingClientRect().top / (el.offsetHeight * 0.62),
        0, 1
      );
      setProgress(p);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    const update = () => setVw(window.innerWidth);
    update();
    window.addEventListener("resize", update, { passive: true });
    return () => window.removeEventListener("resize", update);
  }, []);

  const isXs     = vw > 0 && vw < 400;
  const isSm     = vw >= 400 && vw < 600;
  const isMd     = vw >= 600 && vw < 1024;
  const isLg     = vw >= 1024;
  const isMobile = vw > 0 && vw < 600;
  const isSmall  = vw > 0 && vw < 1024;

  /* ── Font sizes ── */
  const titleFontSize = isLg ? "90px"
    : isMd ? "54px"
    : isSm ? "38px"
    : "30px";

  const subtitleFontSize = isLg ? "52px"
    : isMd ? "26px"
    : isSm ? "17px"
    : "15px";

  /* ── Scroll animation (unchanged) ── */
  const textEnterT  = ease(clamp(progress / 0.75, 0, 1));
  const textScale   = lerp(0.92, 1.0, textEnterT);
  const textOpacity = lerp(0.75, 1.0, textEnterT);

  /*
   * ── MOBILE LAYOUT ──
   *
   * Card orbit center is shifted DOWN by cardCenterOffsetVh from the 50% mark.
   * Orbit vertical radius (ry) on mobile:
   *   sm (400-599): ry = 24vh  → orbit bottom = 50 + 8 + 24 = 82vh from top
   *   xs (< 400):   ry = 22vh  → orbit bottom = 50 + 8 + 22 = 80vh from top
   *   md (600-1023):ry = 22vh  → orbit bottom = 50 + 5 + 22 = 77vh from top
   *
   * Title top:
   *   Sits above the orbit top edge: 50 + offsetVh - ry
   *   sm: 50 + 8 - 24 = 34vh → title pinned at ~5% (safe margin above 34vh)
   *   We use a fixed top: 5% which is well above the orbit's top edge.
   *
   * Subtitle top:
   *   Sits just below the orbit bottom edge + a small gap.
   *   sm: 82vh from top → top: 83%
   *   xs: 80vh from top → top: 81%
   *   md: 77vh from top → top: 78%
   */
  const cardCenterOffsetVh = isLg ? 0 : isMd ? 5 : 8;

  // Orbit ry values (must match HeroCard exactly)
  const orbitRy = isLg ? 30 : isMd ? 22 : isSm ? 24 : 22;

  // Orbit center % from top (50 + offset)
  const orbitCenterPct = 50 + cardCenterOffsetVh;

  // Bottom edge of orbit in vh ≈ orbitCenterPct + orbitRy
  // Add 2vh gap so subtitle clears the lowest card
  const subtitleTopPct = isLg ? 62
    : Math.min(orbitCenterPct + orbitRy + 2, 92); // cap at 92% so it's always visible

  return (
    <div ref={sectionRef} style={{ height: "300vh", position: "relative" }}>
      <div
        id="home-banner"
        style={{
          position: "sticky",
          top: 30,
          height: "100vh",
          overflow: "hidden",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Grid background */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundImage:
              "linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px)," +
              "linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px)",
            backgroundSize: "clamp(32px, 4vw, 48px) clamp(32px, 4vw, 48px)",
          }}
        />

        {/* ── TITLE ──
            Desktop: centered behind cards (zIndex 15, original).
            Mobile/tablet: top zone, above cards (zIndex 30). */}
        <div
          style={{
            position: "absolute",
            left: "50%",
            transform: `translateX(-50%) scale(${textScale})`,
            ...(isLg
              ? { zIndex: 15 }                    // desktop — original, no top
              : { top: isMd ? "5%" : "5%", zIndex: 30 }
            ),
            textAlign: "center",
            width: "92vw",
            maxWidth: "1300px",
            opacity: textOpacity,
            willChange: "transform, opacity",
            padding: isSmall ? "0 16px" : "0",
          }}
        >
          <h1
            style={{
              fontFamily: "Inter",
              fontSize: titleFontSize,
              fontWeight: 900,
              color: "white",
              margin: 0,
              lineHeight: 1.05,
              whiteSpace: "normal",
              overflowWrap: "break-word",
              wordBreak: "break-word",
              letterSpacing: "-0.02em",
            }}
          >
            Deception from
            <br />
            Click to the Doorstep
          </h1>
        </div>

        {/* ── SUBTITLE ──
            Desktop: top: 62%, zIndex 16 (original).
            Mobile/tablet: top = just below card ring bottom edge, zIndex 30. */}
        <div
          style={{
            position: "absolute",
            top: `${subtitleTopPct}%`,
            left: "50%",
            transform: `translateX(-50%) scale(${textScale})`,
            width: isMobile ? "88vw" : "92vw",
            maxWidth: "1300px",
            zIndex: isLg ? 16 : 30,
            textAlign: "center",
            pointerEvents: "none",
            opacity: textOpacity,
            willChange: "transform, opacity",
            padding: isSmall ? "0 8px" : "0",
          }}
        >
          <p
            style={{
              fontSize: subtitleFontSize,
              fontWeight: 500,
              color: "white",
              margin: 0,
              lineHeight: 1.3,
              opacity: 0.88,
              marginTop: isLg ? "30px" : "0",
            }}
          >
            A closer look at the risks in India's gig workforce.
          </p>
        </div>

        {/* ── Cards layer ── */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            pointerEvents: "none",
            overflow: "hidden",
            zIndex: 25,
          }}
        >
          {CARDS.map(c => (
            <HeroCard
              key={c.id}
              card={c}
              progress={progress}
              vw={vw}
              cardCenterOffsetVh={cardCenterOffsetVh}
            />
          ))}
        </div>
      </div>
    </div>
  );
}
